export const AIRCRAFT_FUEL={carrier:{fighter:30,bomber:210},airbase:{fighter:44,bomber:300}};
export const aircraftFuel=(type,hostType)=>AIRCRAFT_FUEL[hostType]?.[type]??TYPES[type]?.fuel??0;
export const nuclearRange=u=>u.type==='silo'?360:u.type==='submarine'?18:u.type==='bomber'?5:0;
export function operationRanges(u){if(!u||u.dead||u.landed)return [];const t=TYPES[u.type],ranges=[];if(t.radar)ranges.push({kind:'radar',radius:t.radar,label:'RADAR'});if(u.type==='submarine'||['carrier','fighter'].includes(u.type)&&u.mode==='antisub')ranges.push({kind:'sonar',radius:u.mode==='passive'?2.5:u.mode==='antisub'?8:5,label:u.mode==='passive'?'PASSIVE SONAR':'SONAR'});if(['launch','nuclear'].includes(u.mode)&&nuclearRange(u))ranges.push({kind:'weapon',radius:nuclearRange(u),global:u.type==='silo',label:u.type==='silo'?'ICBM / GLOBAL':u.type==='submarine'?'MRBM':'SRBM'});else if(t.range&&!(u.type==='submarine'&&u.mode==='passive')&&!(u.type==='carrier'&&u.mode!=='antisub'))ranges.push({kind:'weapon',radius:t.range,label:['carrier','fighter'].includes(u.type)&&u.mode==='antisub'?'DEPTH CHARGE':u.type==='silo'?'AIR DEFENSE':'CONVENTIONAL'});if(t.domain==='air')ranges.push({kind:'fuel',radius:u.fuel/2,label:'RETURN FUEL CAPACITY'});if(['carrier','airbase'].includes(u.type)&&['fighter','bomber'].includes(u.mode))ranges.push({kind:'fuel',radius:aircraftFuel(u.mode,u.type)/2,label:u.mode.toUpperCase()+' RETURN FUEL CAPACITY'});return ranges;}
// Selection describes the current action; local sensor coverage is a separate map layer.
export function selectionRanges(u,sim=null){let ranges=operationRanges(u);if(sim&&u&&!u.dead&&!u.landed&&TYPES[u.type].domain==='air'){const home=sim.units.find(h=>h.id===u.homeId&&!h.dead);ranges=ranges.filter(r=>r.kind!=='fuel');if(sim.allied(u.team,sim.playerTeam)){const d=home?distance(u,home):Infinity,a=u.fuel/2,b=d<=u.fuel?Math.sqrt(Math.max(0,u.fuel*u.fuel-d*d))/2:0;ranges.push({kind:'fuel',radius:home?a:0,x:home?wrapLongitude(home.x+longitudeDelta(home.x,u.x)/2):u.x,y:home?(home.y+u.y)/2:u.y,ellipse:home?{a,b,angle:Math.atan2(u.y-home.y,longitudeDelta(home.x,u.x))}:null,label:home&&d<=u.fuel?'RETURN FUEL CAPACITY':'NO RETURN FUEL'});}}if(u?.type==='radar')return ranges;const nuclear=['launch','nuclear'].includes(u?.mode)&&nuclearRange(u),host=['airbase','carrier'].includes(u?.type)&&['fighter','bomber'].includes(u?.mode);if(u?.type==='bomber')return ranges.filter(r=>r.kind==='weapon'||r.kind==='fuel');if(nuclear||u?.type==='silo')return ranges.filter(r=>r.kind==='weapon');if(host)return ranges.filter(r=>r.kind==='fuel');return ranges.filter(r=>r.kind!=='radar');}
export const TRAIL_SECONDS=35;
export const CONTACT_MEMORY_SECONDS=12,DESTROYED_MARK_SECONDS=6;
export const contactAge=(ghost,time)=>Number.isFinite(ghost.age)?ghost.age:Number.isFinite(ghost.lastSeen)?Math.max(0,time-ghost.lastSeen):Infinity;
export const contactOpacity=(ghost,time)=>.18*Math.max(0,1-contactAge(ghost,time)/CONTACT_MEMORY_SECONDS);
export function returnFuelStatus(u,home){const required=home&&!home.dead?distance(u,home):Infinity;return {reachable:required<=u.fuel,margin:u.fuel-required};}
export const FLEET_RADIUS=1;
export const fleetOffset=(i,count=6)=>({x:Math.cos(-Math.PI/2+i*Math.PI*2/count)*FLEET_RADIUS,y:Math.sin(-Math.PI/2+i*Math.PI*2/count)*FLEET_RADIUS});
export const FALLOUT={duration:300,survivorFraction:.2};
export const NUCLEAR={damage:10,damageRadius:2,visualRadius:5,duration:500};
export function blastAppearance(blast){const duration=blast.nuclear?NUCLEAR.duration:12,remaining=clamp(1-blast.age/duration,0,1);return {alpha:blast.nuclear?Math.min(1,remaining*2):Math.min(.7,remaining),radius:blast.nuclear?NUCLEAR.visualRadius*remaining:Math.max(.05,.35*remaining)};}
export function missileArc(m){const dx=longitudeDelta(m.sx,m.tx),dy=m.ty-m.sy;return {dx,dy,rise:m.profile==='direct'?0:Math.min(35,Math.hypot(dx,dy)*.35)};}
export function missilePosition(m,p=m.p){const {dx,dy,rise}=missileArc(m);return {x:wrapLongitude(m.sx+dx*p),y:m.sy+dy*p+4*p*(1-p)*rise,heading:Math.atan2(dy+4*(1-2*p)*rise,dx)};}

